// Consume the Lua data and compute stats
const data = nb.get('readings');
const min = Math.min(...data);
const max = Math.max(...data);
const avg = data.reduce((a, b) => a + b, 0) / data.length;

console.log(`Lua produced ${data.length} readings`);
console.log(`min=${min}  max=${max}  avg=${avg.toFixed(2)}`);

// JS can write back to nb (it's a two-way cell)
nb.set('stats', { min, max, avg });
return { count: data.length, min, max, avg: +avg.toFixed(2) };
